"""Quick direct NTRU lattice-reduction experiment for downhill.

The public relation g = h*f mod q puts (g,f) in the 2N-dimensional lattice
with basis rows (qI,0) and (H,I).  This script is primarily a diagnostic: it
checks whether straightforward LLL/BKZ is already strong enough for the
challenge parameters before spending time on the signature attack.
"""


# This file was *autogenerated* from the file lattice_try.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_20 = Integer(20); _sage_const_0 = Integer(0); _sage_const_0p99 = RealNumber('0.99'); _sage_const_71 = Integer(71); _sage_const_73 = Integer(73); _sage_const_10 = Integer(10)
import json
import sys
import time

from fpylll import BKZ, IntegerMatrix, LLL


path = sys.argv[_sage_const_1 ] if len(sys.argv) > _sage_const_1  else "local_data_500.json"
block_size = int(sys.argv[_sage_const_2 ]) if len(sys.argv) > _sage_const_2  else _sage_const_20 
with open(path) as source:
    data = json.load(source)

N, q = data["N"], data["q"]
h = data["pk_h"]

# A row vector f multiplied by H is the cyclic product f*h.
H = [[h[(column - row) % N] for column in range(N)] for row in range(N)]
rows = []
for i in range(N):
    rows.append([q if i == j else _sage_const_0  for j in range(N)] + [_sage_const_0 ] * N)
for i in range(N):
    rows.append(H[i] + [_sage_const_1  if i == j else _sage_const_0  for j in range(N)])

B = IntegerMatrix.from_matrix(rows)
print(f"reducing {_sage_const_2 *N}D NTRU lattice with BKZ-{block_size}", flush=True)
t0 = time.time()
LLL.reduction(B, delta=_sage_const_0p99 )
print(f"LLL done in {time.time()-t0:.1f}s; first norm²={sum(int(B[0,j])**2 for j in range(2*N))}", flush=True)

if block_size > _sage_const_2 :
    params = BKZ.Param(block_size=block_size, max_loops=_sage_const_2 )
    BKZ.reduction(B, params)
    print(f"BKZ done in {time.time()-t0:.1f}s; first norm²={sum(int(B[0,j])**2 for j in range(2*N))}", flush=True)

def check_pair(g, f):
    return set(g) <= {_sage_const_0 , _sage_const_1 } and set(f) <= {_sage_const_0 , _sage_const_1 } and sum(g) == _sage_const_71  and sum(f) == _sage_const_73 

for row in range(_sage_const_2 *N):
    vector = [int(B[row, col]) for col in range(_sage_const_2 *N)]
    for sign in (_sage_const_1 , -_sage_const_1 ):
        g = [sign * value for value in vector[:N]]
        f = [sign * value for value in vector[N:]]
        if check_pair(g, f):
            print(f"FOUND sparse pair in basis row {row}: f weight={sum(f)}, g weight={sum(g)}")
            if "true_f" in data:
                print("matches true f up to rotation:", any(f == data["true_f"][r:] + data["true_f"][:r] for r in range(N)))
            sys.exit(_sage_const_0 )

print("no direct sparse secret row found")
for row in range(min(_sage_const_10 , _sage_const_2 *N)):
    vector = [int(B[row, col]) for col in range(_sage_const_2 *N)]
    print(row, sum(value*value for value in vector), min(vector), max(vector))

